            id: 'phy_mp_009',
            question: 'The work function of a metal is 4 eV. The threshold wavelength for photoelectric emission is: (h = 6.6 × 10⁻³⁴ J·s, c = 3 × 10⁸ m/s, 1 eV = 1.6 × 10⁻¹⁹ J)',
            options: ['3100 Å', '4100 Å', '5100 Å', '6100 Å'],
            correctAnswer: 0,
