            question: 'The de Broglie wavelength of an electron accelerated through a potential difference of 100 V is approximately: (h = 6.6 × 10⁻³⁴ J·s, m = 9.1 × 10⁻³¹ kg, e = 1.6 × 10⁻¹⁹ C)',
            options: ['1.23 Å', '0.123 Å', '12.3 Å', '0.0123 Å'],
